question.answer:
package main

type Form struct {
	Applicant string
	Stamps    int
}

func stamp(f Form) Form {
	f.Stamps++
	return f
}

func stampAndCount(f Form) (Form, int) {
	stamped := stamp(f)
	return stamped, f.Stamps
}

