question.answer:
package main

type Clock struct {
	Hour, Minute int
}

func newClock(hour, minute int) *Clock {
	return &Clock{Hour: hour, Minute: minute}
}

func tick(c *Clock) {
	c.Minute++
	if c.Minute == 60 {
		c.Minute = 0
		c.Hour++
	}
	if c.Hour == 24 {
		c.Hour = 0
	}
}

func swap(a, b *Clock) {
	*a, *b = *b, *a
}

