question.answer:
package main

type Position struct {
	Row, Col int
}

type Dock struct {
	At Position
}

type Robot struct {
	Name  string
	At    Position
	Trips int
	Home  *Dock
}

func moved(p Position, rows, cols int) Position {
	p.Row += rows
	p.Col += cols
	return p
}

func drive(r *Robot, rows, cols int) {
	r.At = moved(r.At, rows, cols)
	r.Trips++
}

func swapHomes(a, b *Robot) {
	a.Home, b.Home = b.Home, a.Home
}

func atHome(r *Robot) bool {
	if r.Home == nil {
		return false
	}
	return r.At == r.Home.At
}

testcode.text:
d := Dock{At: Position{0, 0}}
r := Robot{Name: "R2", At: Position{2, 1}, Home: &d}
p := Position{1, 1}
fmt.Println(moved(p, 2, 3), p)
drive(&r, -2, -1)
fmt.Println(r.At, r.Trips, atHome(&r))

r := Robot{Name: "R4", At: Position{4, 4}}
drive(&r, -4, -4)
fmt.Println(r.At, r.Trips, atHome(&r))

a := Dock{At: Position{0, 0}}
b := Dock{At: Position{5, 5}}
r1 := Robot{Name: "R1", At: Position{0, 0}, Home: &a}
r2 := Robot{Name: "R2", At: Position{5, 5}, Home: &b}
r3 := Robot{Name: "R3", At: Position{0, 0}, Home: &a}
swapHomes(&r1, &r2)
fmt.Println(atHome(&r1), atHome(&r2), atHome(&r3))
a.At = Position{3, 3}
drive(&r2, -2, -2)
fmt.Println(atHome(&r2), atHome(&r3), r2.Trips)
